function New-Exp123CollectorCoverage {
 param([string]$RunId,[string]$JsonlPath,[string]$SummaryPath,[int]$CollectorDurationSeconds,[int]$IntervalMilliseconds,[string]$CollectorProcessStartedAt,[string]$CoreInvocationStartedAt,[string]$CoreInvocationCompletedAt,[string]$CollectorProcessCompletedAt)
 $lines=@(Get-Content -LiteralPath $JsonlPath -ErrorAction SilentlyContinue | Where-Object { $_.Trim() });$valid=@();$all=@();$invalid=0
 foreach($line in $lines){try{$s=$line|ConvertFrom-Json -ErrorAction Stop;$d=[DateTimeOffset]::Parse([string]$s.timestamp);$all+=$d;if($null -eq $s.failure -or [string]::IsNullOrWhiteSpace([string]$s.failure)){$valid+=$d}}catch{$invalid++}}
 $failures=$null;try{$failures=[int]((Get-Content -LiteralPath $SummaryPath -Raw|ConvertFrom-Json).failures)}catch{$failures=1}
 $ordered=$true;for($i=1;$i -lt $all.Count;$i++){if($all[$i]-lt$all[$i-1]){$ordered=$false}}
 $start=[DateTimeOffset]::Parse($CoreInvocationStartedAt);$end=[DateTimeOffset]::Parse($CoreInvocationCompletedAt);$first=if($valid.Count){$valid[0]}else{$null};$last=if($valid.Count){$valid[$valid.Count-1]}else{$null};$coverStart=$null-ne$first -and $first -le$start;$coverEnd=$null-ne$last -and $last -ge$end
 $status=if($valid.Count -gt 1 -and $invalid -eq 0 -and $failures -eq 0 -and $ordered -and $coverStart -and $coverEnd){'COLLECTOR_COVERAGE_PASSED'}else{'COLLECTOR_COVERAGE_FAILED'}
 [ordered]@{runId=$RunId;collectorDurationSeconds=$CollectorDurationSeconds;intervalMilliseconds=$IntervalMilliseconds;collectorProcessStartedAt=$CollectorProcessStartedAt;collectorFirstValidSampleAt=if($first){$first.ToUniversalTime().ToString('o')}else{$null};coreInvocationStartedAt=$CoreInvocationStartedAt;coreInvocationCompletedAt=$CoreInvocationCompletedAt;collectorProcessCompletedAt=$CollectorProcessCompletedAt;collectorLastValidSampleAt=if($last){$last.ToUniversalTime().ToString('o')}else{$null};collectorFirstSampleCoveringCoreEndAt=if($coverEnd){$last.ToUniversalTime().ToString('o')}else{$null};validSampleCount=$valid.Count;invalidSampleCount=$invalid;collectorFailures=$failures;coversCoreStart=$coverStart;coversCoreEnd=$coverEnd;timestampsNonDecreasing=$ordered;coverageStatus=$status;failureType=if($status -eq 'COLLECTOR_COVERAGE_PASSED'){$null}else{'COLLECTOR_COVERAGE_FAILED'}}
}
function Assert-Exp123CollectorCoverage([string]$CoveragePath){$c=Get-Content $CoveragePath -Raw|ConvertFrom-Json;if($c.coverageStatus-ne'COLLECTOR_COVERAGE_PASSED'-or-not$c.coversCoreStart-or-not$c.coversCoreEnd-or$c.invalidSampleCount-ne0-or$c.collectorFailures-ne0){throw 'COLLECTOR_COVERAGE_FAILED'};if([string]::IsNullOrWhiteSpace([string]$c.collectorFirstSampleCoveringCoreEndAt)){throw 'COLLECTOR_POST_CORE_SAMPLE_MISSING'}}
